// Reviewed bilingual expansion data. Generated by deploy/build_world50.py.
const WORLD50={"it":{"name":"Италия","town":"Порто-Белла","flag":"🇮🇹","idx":4,"rate":100,"symbol":"€","color":"#e3a75f","music":"mandolin50","chapters":[{"id":"01","title":"Чемодан без колёс","text":"Ава передаёт Валере письмо реставратора Луки. В вымышленной Порто-Белле исчезает мастерская, чей штамп встречался в счетах Дюваля. На вокзале вместо встречающего — голубь и карта из трёх частей.","reply":"В Париже были справки. Здесь хотя бы карта съедобного цвета.","game":"route","other":null},{"id":"02","title":"Ключ под базиликом","text":"Синьора Роза сдаёт угол во дворе. Ключ лежит под одним из горшков, но сначала нужно разобрать перепутанные посылки соседей. В одной — старая фотография мастерской.","reply":"Базилик охраняет недвижимость лучше моего прошлого риелтора.","game":"sort","other":"house1"},{"id":"03","title":"Кофе без большой кружки","text":"Бариста Джанни не понимает заказ «кофе в ведре». Он показывает три рецепта и замечает на фотографии человека из компании «Футуро». Тот скупает весь квартал.","reply":"Это не маленький кофе. Это большая ответственность.","game":"recipe","other":"eat"},{"id":"04","title":"Маргарита на колёсах","text":"Курьер София берётся показать город за помощь с доставкой. Заказы уедут не туда, если перепутать мосты и площади. У закрытой мастерской всё ещё горит свет.","reply":"Главное — доставить пиццу круглой, а не географической картой.","game":"route","other":"shift"},{"id":"05","title":"Мастерская живых вещей","text":"Лука чинит вывеску и рассказывает: владельцев вынуждают продать дома под «музей пустых фасадов». Его собственный договор оказался подписан чужой рукой. Помоги восстановить мозаику с подлинной датой.","reply":"Я тоже немного реставратор: жизнь уже несколько раз собирал.","game":"mosaic","other":"lesson"},{"id":"06","title":"Рынок трёх бабушек","text":"Роза, Тереза и Бьянка спорят, чьи помидоры помнят настоящее солнце. За общим заказом выясняется: каждому торговцу показали разную схему реконструкции. Нужно собрать все версии.","reply":"Три бабушки — уже совет директоров, только эффективнее.","game":"sort","other":"house2"},{"id":"07","title":"Ларёк с характером","text":"Соседи готовы покупать у Валеры, если он откроет настоящее местное дело. Доход поможет печатать обращения, а чеки покажут, что квартал живой, а не заброшенный.","reply":"Международная сеть «У Валеры»: снова одна точка, зато своя.","game":"recipe","other":"business"},{"id":"08","title":"Сиеста не алиби","text":"Представитель «Футуро» заявляет, что мастерская не работала год. Джанни помнит недавний заказ, но время на чеке залито кофе. Восстанови последовательность событий по трём квитанциям.","reply":"Перерыв после обеда не означает закрытие навсегда.","game":"logic","other":"shift"},{"id":"09","title":"Голубь нотариуса","text":"Голубь Песто уносит ленточку от архивной папки. По цветам на площади Лука узнаёт маршрут нотариуса. Найди дорогу к архиву, пока птица не решила открыть собственный документооборот.","reply":"Этому голубю нужен не корм, а электронная подпись.","game":"route","other":"trash"},{"id":"10","title":"Паста не требует ножниц","text":"Тереза приглашает соседей на ужин примирения. За столом бывший курьер признаётся, что возил одинаковые договоры с разными подписями. Сначала приготовь заказ по рецепту.","reply":"Ножницы убрал. Дипломатический кризис предотвращён.","game":"recipe","other":"eat"},{"id":"11","title":"Маска на карнавале","text":"На карнавале София замечает посредника с портфелем. Среди похожих масок нужно найти ту, что изображена на приглашении. Внутри портфеля — список будущих выселений.","reply":"Если все в масках, честнее становится только голубь.","game":"mosaic","other":"date"},{"id":"12","title":"Чек на пустой дом","text":"В списке есть дом, которого не существует. Лука просит разнести документы по адресам и отделить реальные здания от нарисованных. Так обнаруживается склад под видом жилого дома.","reply":"Недвижимость настолько элитная, что её даже нет.","game":"sort","other":"lesson"},{"id":"13","title":"Ночь на канале","text":"Склад открывают после полуночи. Рыбак Марко предлагает лодку и честное правило: не трогать чужие вещи, только зафиксировать доставку. Построй безопасный маршрут между причалами.","reply":"Водный транспорт: бензина нет, зато есть уважение к вёслам.","game":"route","other":"shift"},{"id":"14","title":"Печать из сахара","text":"На коробках обнаруживаются «старинные печати», сделанные вчера. Джанни сравнивает их с формами для печенья. Разбери признаки подделки: материал, дату и совпадение номера.","reply":"Я думал, липовые документы — это про дерево.","game":"logic","other":"house3"},{"id":"15","title":"Роза собирает двор","text":"Квартал расколот слухами о компенсациях. Роза просит приготовить общий стол, а Валера открыто показывает найденные счета. Соседи решают действовать вместе, без тайных сделок.","reply":"Общее собрание прошло единогласно: сначала поесть.","game":"recipe","other":"businessCollect"},{"id":"16","title":"Архив без драконов","text":"Архивистка Бьянка даёт доступ к старым планам. Футуро подменили границы участка. Собери мозаику плана и найди проход, который по закону принадлежит жителям.","reply":"Самое страшное в архиве — не пыль, а одинаковые папки.","game":"mosaic","other":"lesson"},{"id":"17","title":"Скутер с посланием","text":"Софии угрожают штрафом за доставку доказательств. Валера собирает новый маршрут через открытые улицы. На сиденье скутера лежит записка: «Не все в компании согласны».","reply":"Скутер умеет хранить тайны. Главное — не хранить их под дождём.","game":"route","other":"transport1"},{"id":"18","title":"Человек без визитки","text":"Бухгалтер Энцо приносит журнал поставок. Его нельзя выдавать компании, пока копии не попадут в независимый архив. Сверь суммы и отправь правильные пакеты.","reply":"Наконец-то бухгалтер, который приносит деньги в виде доказательств.","game":"logic","other":"shift"},{"id":"19","title":"Серенада для принтера","text":"Накануне слушаний ломается единственный принтер. Лука чинит механизм, Валера раскладывает детали по порядку. Соседи называют это самым полезным концертом в городе.","reply":"Бис будет, когда он перестанет жевать бумагу.","game":"sort","other":"businessCollect"},{"id":"20","title":"Площадь не продаётся","text":"На открытом слушании директор Футуро показывает красивую схему без жителей. Валера отвечает документами и настоящими адресами. Выбери доводы, которые подтверждаются архивом.","reply":"Рендер красивый. Только нас забыли дорисовать.","game":"logic","other":"house4"},{"id":"21","title":"Мастерская возвращается","text":"Проект приостановлен, но квартал ещё нужно восстановить. Лука отдаёт Валере ключ от общей мастерской. Верни вывеску и собери уцелевшую мозаику по фотографии.","reply":"Теперь у меня есть ключ, который не нужно прятать под базиликом.","game":"mosaic","other":"shift"},{"id":"22","title":"Соседский фестиваль","text":"Жители устраивают праздник вместо презентации застройщика. Нужны еда, свет и сцена. Координируй заказы так, чтобы никто не остался без ужина.","reply":"Премиум-пропуск на фестиваль — помочь убрать столы.","game":"recipe","other":"eat"},{"id":"23","title":"Посылка из Лунцзяна","text":"В мастерскую приходит нефритовая деталь и письмо мастера Линя. Журнал Энцо связан с китайским рынком ремесленников: там та же фирма прячет чужие работы за поддельными номерами.","reply":"Я ещё не выучил «грацие», а чемодан уже смотрит на восток.","game":"sort","other":"lesson"},{"id":"24","title":"Обещание на набережной","text":"София и Лука готовят копии доказательств для Линя. Валера не убегает от проблем: теперь он сам выбирает помочь следующему кварталу. Проверь последний маршрут доставки.","reply":"Раньше я терял адреса. Теперь оставляю друзей.","game":"route","other":"businessCollect"},{"id":"25","title":"Чао — не прощай","text":"Роза вручает пакет фокаччи в дорогу. Площадь сохранена, мастерская принадлежит соседям, счета переданы Аве. Валера собирает памятную мозаику и билет в Лунцзян — город каналов, чая и новых историй.","reply":"Песто, квартиру не продавай. Я знаю твоего риелтора.","game":"mosaic","other":null}],"tag":"Площади, эспрессо и мастерская, которую не продать","food":["Фокачча с розмарином","Аранчини с рисом","Эспрессо у Джанни","Панини с моцареллой","Лимонная гранита","Пицца «Маргарита»","Риболлита — овощной суп","Лазанья синьоры Розы","Рикотта с мёдом","Ризотто с грибами","Лингвини с морепродуктами","Оссобуко с полентой","Ужин на площади","Тирамису от Терезы"],"foodEmoji":["🫓","🍙","☕","🥪","🍋","🍕","🥣","🍝","🥛","🍚","🍤","🍖","🍽️","🍰"],"housing":["Скамейка у старой площади","Палатка под лоджией","Комната над пекарней","Студия во дворе Розы","Квартира с террасой","Лофт в старой мастерской","Вилла над заливом"],"edu":["Новичок в Порто-Белле","Город без языкового барьера","Курсы пекарей и бариста","Школа городских ремёсел","Институт реставрации","Академия семейного дела"],"jobs":["Раздатчик афиш на площади","Грузчик рыбного рынка","Курьер с пиццей","Смотритель палаццо","Таксист на набережной","Продавец в гастрономии","Управляющий тратторией","Директор ремесленного кооператива","Смотритель чистой площади","Почтальон между каналами","Пиццайоло у дровяной печи","Патрульный карабинер","Учитель в мастерской Луки","Служащий городской коммуны","Советник квартала"],"business":["Тележка с гранитой","Пиццерия «У Валеры»","Мастерская скутеров","Траттория у Розы","Сеть лавок гастрономии","Джазовый дворик «Чао»"],"transport":["Пешком по брусчатке","Самокат с площади","Велосипед почтальона","Винтажный скутер","Грузовой трёхколёсник","Скутер «Мятная стрела»","Городская микролитражка","Фургон пекаря","Купе «Белла»","Электрокар набережной","Родстер Ривьеры","Лимузин кинофестиваля"],"girls":["София, велокурьер","Джулия, реставратор","Кьяра, бариста","Аличе, фотограф"],"petNames":["Голубь Песто","Соня Канноли","Пёс Бискотто","Ёж Ризотто","Попугай Чао","Кот Джелато"],"glossary":"Пьяцца — площадь; траттория — небольшое семейное кафе; палаццо — городской дворец; грацие — спасибо; чао — привет или пока. Для прохождения не нужно знать итальянский: заказы и маршруты всегда подписаны.","eggTitle":"Песто и закон сохранения пасты"},"cn":{"name":"Китай","town":"Лунцзян","flag":"🇨🇳","idx":5,"rate":15,"symbol":"¥","color":"#edb85b","music":"teahouse50","chapters":[{"id":"01","title":"Город под красными фонарями","text":"В вымышленном Лунцзяне Валеру встречает мастер Линь. Посылка из Италии — часть старой вывески ремесленного рынка. Компания «Нефритовый горизонт» объявила все мастерские нелегальными.","reply":"Новый город. Старый талант: оказаться рядом с чужими документами.","game":"route","other":null},{"id":"02","title":"Баоцзы по адресу","text":"Хозяйка паровой лавки Мэй показывает район через заказы. Баоцзы — булочки на пару, а не загадка на знание языка. На каждом заказе понятный значок и номер дома.","reply":"Если внутри еда, перевод уже почти не нужен.","game":"sort","other":"eat"},{"id":"03","title":"Комната над чайной","text":"Линь договаривается о ночлеге у госпожи Чэнь. Взамен нужно подготовить чайный стол для соседей. На старом подносе сохранился настоящий регистрационный знак рынка.","reply":"Главное — не перепутать чайную церемонию с заливкой радиатора.","game":"tea","other":"house1"},{"id":"04","title":"Маршрут без иероглифического экзамена","text":"Курьер Ань настраивает карту: цвета, пересадки и русские подписи. Она заметила, что доставкам в старый рынок присваивают чужие номера. Проверь маршрут до сортировочного центра.","reply":"Цвет линии выучил. Теперь бы не уехать вместе с посылкой.","game":"route","other":"shift"},{"id":"05","title":"Печать, которая не врёт","text":"Линь объясняет, как проверять заказы: номер, количество и штамп мастера должны совпадать. В новой системе метки подменили. Сверь реальные квитанции, а не красивые обещания.","reply":"Три проверки. И ни одной справки о справке. Прогресс.","game":"logic","other":"lesson"},{"id":"06","title":"Ночной рынок просыпается","text":"Мэй собирает торговцев на вечернюю смену. Продажи докажут, что рынок нужен людям. Разложи блюда по заказам; один покупатель заказывает только пар и серьёзный вид.","reply":"Пар бесплатный. За серьёзный вид придётся доплатить.","game":"sort","other":"house2"},{"id":"07","title":"Своё маленькое большое дело","text":"Ань помогает Валере открыть местную точку. Нужны честные чеки и общая касса для ремонта фонарей. Бизнесы Италии продолжают работать по прежним правилам управляющей компании.","reply":"Филиал «У Валеры» теперь умеет говорить на языке чеков.","game":"tea","other":"business"},{"id":"08","title":"Панда ставит обновление","text":"Студентка Цзя чинит маленького робота-панду. Он хранит снимок старой базы, но сперва просит «обновить драйвер бамбука». Собери цепь питания по образцу.","reply":"Перезагрузка помогла бы и моему бывшему начальнику.","game":"circuit","other":"lesson"},{"id":"09","title":"Склад одинаковых коробок","text":"В сортировочном центре Ань находит упаковки ремесленников под маркой чужой компании. Раздели их по настоящим штампам. Среди коробок — подлинный журнал отправлений.","reply":"Даже одинаковые коробки заслуживают индивидуального подхода.","game":"sort","other":"shift"},{"id":"10","title":"Семь глотков тишины","text":"Госпожа Чэнь приглашает уставших мастеров на чай. За спокойным разговором выясняется: чиновнику показали поддельный отчёт об опасной проводке рынка. Сохрани правильные параметры заваривания.","reply":"Семь глотков без уведомлений. Вот это подписка.","game":"tea","other":"eat"},{"id":"11","title":"Фонарь с памятью","text":"Старый фонарщик Бо помнит, когда меняли проводку. На фонарях стоят номера партии. Восстанови рисунок цепи: он приведёт к настоящему заказу на ремонт.","reply":"Этот фонарь помнит больше, чем мой пароль от почты.","game":"circuit","other":"date"},{"id":"12","title":"Правильная пересадка","text":"Копии нужно отвезти независимому инженеру. Прямая линия закрыта на ремонт, но карта показывает обход. Ань просит не геройствовать: нужная пересадка лучше короткого пути через ворота.","reply":"Не любой короткий путь экономит время в полиции.","game":"route","other":"transport1"},{"id":"13","title":"Инженер против презентации","text":"Инженер Вэй проверяет цепи и находит заменённые пломбы. «Нефритовый горизонт» рисовал аварии в отчётах. Проверь схемы по образцу и отдели реальные дефекты от выдуманных.","reply":"Красивый график ток не проводит. Проверено инженером.","game":"circuit","other":"house3"},{"id":"14","title":"Лапша длиннее совещания","text":"Мэй устраивает ужин для жителей и инженеров. Нужно раздать заказы, пока люди обсуждают общий план. Вэй предлагает публичную проверку рынка вместо закрытого заседания.","reply":"Лапшу здесь тянут на кухне, а не в обещаниях.","game":"sort","other":"eat"},{"id":"15","title":"Архив из трёх копий","text":"Цзя восстанавливает журнал робота. Поставки, печати и даты должны совпасть сразу в трёх независимых записях. Найди несовпадения, не удаляя ни одной исходной копии.","reply":"Резервная копия — лучший друг героя после тёплой булочки.","game":"logic","other":"lesson"},{"id":"16","title":"Чайный двор держится вместе","text":"Компания предлагает Чэнь личную компенсацию за молчание. Она отказывается и открывает двор для общего собрания. Подготовь чай так, чтобы все успели высказаться.","reply":"Слово «общий» оказалось сильнее слова «выгодный».","game":"tea","other":"businessCollect"},{"id":"17","title":"Грузовой велосипед Ань","text":"Для независимой проверки нужны приборы и безопасная доставка. Ань собирает грузовой маршрут из нескольких остановок. Валера помогает отвезти инструменты, не подменяя документы по дороге.","reply":"У этого велосипеда грузоподъёмность выше моего доверия к презентациям.","game":"route","other":"shift"},{"id":"18","title":"Пломба номер ноль","text":"На контрольном приборе стоит номер, отсутствующий в реестре. Линь находит тот же знак на детали из Италии. Это не местная ошибка, а цепочка подмен между компаниями.","reply":"Номер ноль. Даже у моего первого бизнеса был номер.","game":"logic","other":"businessCollect"},{"id":"19","title":"Свет возвращается","text":"Бо и Вэй готовы восстановить освещение законно и без спешки. Собери рабочую цепь фонарей. Соседи впервые видят улицу такой, какой она была до бумажной аварии.","reply":"Самый красивый спецэффект — когда снова работает обычный свет.","game":"circuit","other":"house4"},{"id":"20","title":"Открытая проверка","text":"Инженер, жители и представители города сверяют поставки на глазах у всех. Валера предъявляет итальянский журнал и китайские квитанции. Выбери подтверждённые выводы, а не громкие обвинения.","reply":"Доказательства громче мегафона. И батарейки не нужны.","game":"logic","other":"shift"},{"id":"21","title":"Мастерская под своим именем","text":"Рынку возвращают регистрацию. Линь просит не торопиться с праздником: сначала вернуть мастерам их настоящие вывески. Собери и развези заказы с правильными именами.","reply":"Главный бренд — человек, который это сделал.","game":"sort","other":"lesson"},{"id":"22","title":"Фестиваль тысячи огней","text":"Мэй готовит еду, Бо — фонари, Цзя — робота-ведущего. Валере достаётся почётная обязанность не запутать питание сцены. Подготовь рисунок огней к вечеру.","reply":"Главное — чтобы панда не начала обновление во время концерта.","game":"circuit","other":"eat"},{"id":"23","title":"Ответ из Порто-Беллы","text":"София присылает фото восстановленной площади. Две мастерские на разных концах света теперь обмениваются настоящими работами. Подготовь ответную посылку: чай, рисунок и копию решения.","reply":"Международная доставка добра. Без графы «срочно перепродать».","game":"sort","other":"businessCollect"},{"id":"24","title":"За одним чайным столом","text":"Госпожа Чэнь собирает всех, кто помог рынку. Валера смотрит на карту: теперь на ней не места побега, а люди, к которым можно написать. Приготовь последний чай для друзей.","reply":"Оказалось, дом иногда помещается вокруг одного стола.","game":"tea","other":"date"},{"id":"25","title":"Новая глава — не конец","text":"Рынок живёт, мастерские работают под своими именами, доказательства переданы Аве. Вечером Валера и Цзя запускают узор фонарей над каналом. Впереди развитие дома, местных дел и следующий круг — уже с памятью о шести городах.","reply":"Панда, только не спрашивай сейчас «сохранить изменения?».","game":"circuit","other":null}],"tag":"Ночной рынок, чайные дворы и тысяча огней","food":["Лепёшка цзяньбин","Баоцзы на пару","Кофе с рынка Мэй","Цзяоцзы — пельмени","Холодный жасминовый чай","Лапша с овощами","Суп с вонтонами","Обед мастера Линя","Соевый пудинг","Рис в глиняном горшке","Рыба с имбирём","Утка с блинчиками","Праздничный хого","Лунный пряник с лотосом"],"foodEmoji":["🫓","🥟","☕","🥟","🍵","🍜","🥣","🍱","🥛","🍚","🐟","🦆","🍲","🥮"],"housing":["Лавка у канала Лунцзяна","Палатка под навесом рынка","Комната над чайной Чэнь","Студия в старом переулке","Квартира у сада фонарей","Лофт над мастерской","Дом с нефритовым садом"],"edu":["Новичок в Лунцзяне","Схемы и маршруты Лунцзяна","Курсы чайных мастеров","Колледж городских технологий","Институт инженерных искусств","Академия торговых кооперативов"],"jobs":["Расклейщик афиш ночного рынка","Сборщик заказов на складе","Курьер на электровелосипеде","Смотритель сада фонарей","Водитель городского такси","Продавец чайной лавки","Управляющий чайным домом","Директор городского технопарка","Работник чистого канала","Почтальон старых переулков","Мастер лапши и баоцзы","Патрульный набережной","Наставник мастерской Линя","Служащий реестра мастеров","Представитель городского совета"],"business":["Тележка с жасминовым чаем","Лапшичная «У Валеры»","Мастерская электровелосипедов","Чайный двор «Тёплый свет»","Сеть городских маркетов","Музыкальный павильон «Фонарь»"],"transport":["Пешком вдоль канала","Складной самокат","Городской велосипед","Электровелосипед курьера","Грузовой электротрицикл","Электроскутер «Лунный заяц»","Городской электрокар","Фургон ночного рынка","Купе «Нефрит»","Смарт-мобиль Лунцзяна","Гран-турер «Красный дракон»","Лимузин фестиваля фонарей"],"girls":["Ань, курьер и картограф","Цзя, инженер робототехники","Юэ, художница фонарей","Лань, чайный мастер"],"petNames":["Горлица Жасмин","Тушканчик Фасоль","Сиба Баоцзы","Красная панда Бамбук","Попугай Лотос","Кот Лунный Пряник"],"glossary":"Баоцзы — булочки на пару; цзяоцзы — пельмени; хого — общий горячий котёл с бульоном; ни хао — привет; се-се — спасибо. Китайский знать не нужно: числа, схемы и инструкции даны на выбранном языке игры.","eggTitle":"Панда и драйвер бамбука"}};
